:root {
  color-scheme: dark;
  --bg: oklch([REDACTED_PHONE]);
  --surface: oklch([REDACTED_PHONE]);
  --surface-strong: oklch([REDACTED_PHONE]);
  --ink: oklch([REDACTED_PHONE]);
  --muted: oklch([REDACTED_PHONE]);
  --cyan: oklch([REDACTED_PHONE]);
  --copper: oklch([REDACTED_PHONE]);
  --line: color-mix(in oklch, var(--cyan) 24%, transparent);
  --max: 1280px;
  font-family: "Avenir Next", Avenir, "Segoe UI", system-ui, sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; background: var(--bg); }
body {
  margin: 0;
  min-width: 320px;
  color: var(--ink);
  background:
    radial-gradient(circle at 76% 26%, color-mix(in oklch, var(--cyan) 12%, transparent), transparent 32rem),
    radial-gradient(circle at 18% 82%, color-mix(in oklch, var(--copper) 10%, transparent), transparent 34rem),
    var(--bg);
}
a { color: inherit; }
.skip-link {
  position: fixed;
  left: 18px;
  top: 12px;
  z-index: 10;
  transform: translateY(-160%);
  padding: 10px 14px;
  background: var(--ink);
  color: var(--bg);
}
.skip-link:focus { transform: none; }
.ambient-grid {
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.18;
  background-image:
    linear-gradient(color-mix(in oklch, var(--cyan) 14%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklch, var(--cyan) 14%, transparent) 1px, transparent 1px);
  background-size: 84px 84px;
  mask-image: linear-gradient(to bottom, black, transparent 76%);
}
.site-header,
main,
footer {
  width: min(var(--max), calc(100% - 48px));
  margin-inline: auto;
  position: relative;
}
.site-header {
  min-height: 92px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--line);
}
.identity { display: flex; align-items: center; gap: 16px; text-decoration: none; line-height: 1.15; font-size: 13px; }
.identity-mark { font-family: Georgia, "Times New Roman", serif; font-size: 42px; color: var(--copper); }
.header-actions { display: flex; align-items: center; gap: 22px; font-size: 14px; }
.header-actions > a { text-underline-offset: 5px; }
.surface-status { display: inline-flex; align-items: center; gap: 9px; color: var(--muted); }
.surface-status i { width: 8px; height: 8px; border-radius: 50%; background: var(--cyan); }
.hero {
  min-height: calc(100vh - 92px);
  display: grid;
  grid-template-columns: minmax(360px, 0.82fr) minmax(540px, 1.18fr);
  align-items: center;
  gap: clamp(28px, 4vw, 72px);
  padding-block: clamp(64px, 9vw, 128px);
}
.hero-copy { position: relative; z-index: 2; }
.hero-context { margin: 0 0 22px; color: var(--copper); font-weight: 700; }
h1,
h2 { text-wrap: balance; }
h1 {
  margin: 0;
  max-width: 720px;
  font-size: clamp(3.2rem, 6.2vw, 5.8rem);
  line-height: 0.98;
  letter-spacing: -0.035em;
  font-weight: 620;
}
.hero-lead {
  max-width: 62ch;
  margin: 32px 0 0;
  color: var(--muted);
  font-size: clamp(1rem, 1.5vw, 1.18rem);
  line-height: 1.75;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 34px; }
.action {
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 0 20px;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 700;
}
.action:focus-visible,
a:focus-visible { outline: 3px solid var(--cyan); outline-offset: 4px; }
.action-primary { background: var(--copper); color: var(--bg); }
.action-primary:hover { background: oklch([REDACTED_PHONE]); }
.action-secondary { border: 1px solid var(--cyan); color: var(--cyan); }
.action-secondary:hover { background: color-mix(in oklch, var(--cyan) 10%, transparent); }
.release-note { max-width: 58ch; margin: 24px 0 0; color: var(--muted); font-size: 0.88rem; line-height: 1.6; }
.network-stage { margin: 0; min-width: 0; }
.network-stage svg { display: block; width: 100%; height: auto; overflow: visible; }
.network-stage figcaption { max-width: 62ch; margin: 4px auto 0; color: var(--muted); font-size: 0.82rem; text-align: center; }
.map-grid path { fill: none; stroke: color-mix(in oklch, var(--cyan) 10%, transparent); stroke-width: 1; }
.map-links path {
  fill: none;
  stroke: var(--cyan);
  stroke-width: 1.5;
  stroke-opacity: 0.68;
  stroke-dasharray: 7 10;
  animation: route-flow 16s linear infinite;
}
.map-links path:nth-child(2n) { stroke: var(--copper); stroke-opacity: 0.55; animation-direction: reverse; }
.map-minor circle { fill: var(--cyan); opacity: 0.65; }
.map-core > circle:nth-of-type(2) { fill: var(--surface); stroke: var(--cyan); stroke-width: 1.5; }
.map-core > circle:nth-of-type(3) { fill: var(--ink); }
.map-core text { fill: var(--muted); font-size: 13px; text-anchor: middle; letter-spacing: 0.08em; }
.map-node circle:first-child { fill: var(--surface); stroke-width: 1.4; }
.map-node circle:nth-child(2) { stroke: none; }
.map-node text { font-size: 16px; font-weight: 700; }
.map-node-cyan circle:first-child { stroke: var(--cyan); }
.map-node-cyan circle:nth-child(2), .map-node-cyan text { fill: var(--cyan); }
.map-node-copper circle:first-child { stroke: var(--copper); }
.map-node-copper circle:nth-child(2), .map-node-copper text { fill: var(--copper); }
@keyframes route-flow { to { stroke-dashoffset: -170; } }
.capability-rail {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-block: 1px solid var(--line);
}
.capability-rail article { padding: 34px clamp(20px, 3vw, 42px); }
.capability-rail article + article { border-left: 1px solid var(--line); }
.capability-rail span,
.section-heading p,
.safety > div > p { color: var(--copper); font-weight: 700; }
.capability-rail h2 { margin: 12px 0 8px; font-size: 1.35rem; }
.capability-rail p { margin: 0; color: var(--muted); line-height: 1.65; }
.explorer { padding-block: clamp(92px, 12vw, 164px); }
.section-heading { max-width: 760px; }
.section-heading p { margin: 0 0 16px; }
.section-heading h2,
.safety h2 { margin: 0; font-size: clamp(2.2rem, 4.5vw, 4.5rem); line-height: 1.02; letter-spacing: -0.03em; }
.lens-strip { margin-top: 54px; display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--line); }
.lens-strip article { min-height: 180px; padding: 26px 22px; border-bottom: 1px solid var(--line); }
.lens-strip article + article { border-left: 1px solid var(--line); }
.lens-strip strong { display: block; font-size: 1.16rem; }
.lens-strip span { display: block; margin-top: 58px; color: var(--muted); line-height: 1.5; }
.safety {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.78fr);
  gap: clamp(42px, 8vw, 112px);
  padding: clamp(48px, 7vw, 92px);
  background: var(--surface);
  border-radius: 14px;
}
.safety > div > p { margin: 0 0 16px; }
.safety dl { margin: 0; }
.safety dl > div { padding-block: 22px; border-bottom: 1px solid var(--line); }
.safety dl > div:first-child { padding-top: 0; }
.safety dt { color: var(--cyan); font-weight: 800; }
.safety dd { margin: 10px 0 0; color: var(--muted); line-height: 1.65; }
footer {
  margin-top: 34px;
  min-height: 110px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  font-size: 0.88rem;
}
footer nav { display: flex; flex-wrap: wrap; gap: 20px; }
footer a { color: var(--ink); text-underline-offset: 5px; }

@media (max-width: 980px) {
  .hero { grid-template-columns: 1fr; min-height: auto; }
  .network-stage { max-width: 760px; margin-inline: auto; }
  .capability-rail { grid-template-columns: 1fr; }
