.safety dl { margin: 0; }
.safety dl > div { padding: 20px 0; border-bottom: 1px solid var(--line); }
.safety dl > div:first-child { padding-top: 0; }
.safety dt { color: var(--jade); font-weight: 760; }
.safety dd { margin: 8px 0 0; color: var(--muted); line-height: 1.6; }
footer { min-height: 112px; margin-top: 32px; display: flex; justify-content: space-between; align-items: center; gap: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 0.86rem; }
footer nav { display: flex; flex-wrap: wrap; gap: 20px; }
footer a { color: var(--ink); text-underline-offset: 5px; }

@media (max-width: 1040px) {
  .hero { grid-template-columns: 1fr; }
  .review-orbit { margin-top: 28px; }
  .safety { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  .site-header, main, footer { width: min(100% - 28px, var(--max)); }
  .site-header { align-items: flex-start; padding-block: 18px; }
  .header-meta { align-items: flex-end; flex-direction: column-reverse; gap: 8px; text-align: right; }
  .header-meta span { font-size: 0.72rem; }
  .hero { padding-block: 64px 88px; }
  h1 { font-size: clamp(3rem, 14vw, 4.5rem); }
  .button { width: 100%; }
  .review-orbit { width: 112%; margin-left: -6%; }
  .orbit-node { width: 126px; }
  .orbit-node i { width: 58px; height: 58px; }
  .orbit-node p { font-size: 0.72rem; }
  .capabilities { grid-template-columns: 1fr; }
  .capabilities article + article { border-left: 0; border-top: 1px solid var(--line); }
  .dry-run li { grid-template-columns: 76px 1fr; }
  .dry-run small { grid-column: 2; }
  .safety { padding: 30px 22px; }
  footer { align-items: flex-start; flex-direction: column; padding-block: 30px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; }
}

