    raw_like_paths = {path for path, record in records.items() if record["raw_or_session_metadata_only"]}
    corpus_paths = sorted(path for path, record in records.items() if is_reference_text(record, args.max_text_bytes))
    oversized_text = sorted(
        path for path, record in records.items()
        if not record["raw_or_session_metadata_only"]
        and int(record["bytes"]) > args.max_text_bytes
        and (PurePosixPath(path).suffix.lower() in TEXT_EXTENSIONS or record["file_class"] in {"workflow", "package_manifest"})
    )

    cache = ContentCache(args.out / "corpus_cache.sqlite")
