    content_sources: dict[str, str] = {}
    missing_remote: list[tuple[str, str]] = []
    cache_inserts: list[tuple[str, bytes, str]] = []

    for path in corpus_paths:
        sha = records[path]["blob_sha"]
        cached = cache.get(sha)
        if cached is not None:
            contents[path], content_sources[path] = cached[0], "cache_verified"
            continue
        local_path = args.repo / path
        if local_path.is_file():
            data = local_path.read_bytes()
            if git_blob_sha(data) == sha:
                contents[path] = data
                content_sources[path] = "worktree_sha_verified"
