        pattern = pattern.replace("\\", "/")
        if len(pattern) >= 4:
            value = (target, kind)
            if value not in pattern_map[pattern]:
                pattern_map[pattern].append(value)

    for path in sorted(candidates):
        add_pattern(path, path, "full_path")
        if "/" in path:
            relative = path.split("/", 1)[1]
            add_pattern(relative, path, "project_relative")
        basename = PurePosixPath(path).name
        if basename_counts[basename] == 1 and len(basename) >= 6:
            add_pattern(basename, path, "unique_basename")
